package EmployeeManagementSystem.entity;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.*;
@Entity @Table(name="employee_separations") @Getter @Setter
public class EmployeeSeparation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="employee_id",unique=true) private Employee employee; private String employeeName; private String userId; private String reason; private LocalDate resignationDate; private LocalDate lastWorkingDate; private Integer noticeDays; private String status="SUBMITTED"; private String exitInterviewNotes; private String hrComment; private Boolean managerCleared=false; private Boolean hrCleared=false; private Boolean financeCleared=false; private Boolean assetCleared=false; private Boolean accessCleared=false; private LocalDate approvedDate; private LocalDate completedDate; private LocalDateTime createdAt; private LocalDateTime updatedAt; @PrePersist void pre(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void upd(){updatedAt=LocalDateTime.now();} }
